def compute(vars):
    old_backlog = vars["v1"]
    new_backlog = vars["v2"]
    change = new_backlog - old_backlog

    return {
        "value": change,
        "trace": {
            "old_backlog_2013": old_backlog,
            "new_backlog_2014": new_backlog,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
